<?php require_once '../includes/auth.php'; require_once '../includes/csrf.php'; require_once '../includes/functions.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('login.php'); verify_csrf(); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; $stmt=db()->prepare('SELECT id,name,email,password,role FROM usuarios WHERE email=? AND status="active" LIMIT 1'); $stmt->execute([$email]); $user=$stmt->fetch(); if(!$email||!$user||!password_verify($password,$user['password'])) { flash('error','Correo o contraseña incorrectos.'); redirect('login.php'); } login_user($user); $target=safe_redirect($_POST['redirect']??'','index.php'); redirect($target);
